        static Vector2[][][] parsed;
        public static Vector2[][][] Contours
        {
            get
            {
                if (parsed != null) return parsed;
                parsed = new Vector2[contours.Length][][];
                for (int r = 0; r < contours.Length; r++)
                {
                    var paths = new List<Vector2[]>();
                    foreach (var path in contours[r].Split('|'))
                    {
                        var points = new List<Vector2>();
                        foreach (var pair in path.Split(' '))
                        {
                            var xy = pair.Split(',');
                            points.Add(new Vector2(float.Parse(xy[0], CultureInfo.InvariantCulture), float.Parse(xy[1], CultureInfo.InvariantCulture)));
                        }
                        paths.Add(points.ToArray());
                    }
                    parsed[r] = paths.ToArray();
                }
                return parsed;
            }
        }
        public static bool Contains(Vector2[] polygon, Vector2 point)
        {
            bool inside = false;
            for (int i = 0, j = polygon.Length - 1; i < polygon.Length; j = i++)
            {
                var a = polygon[i]; var b = polygon[j];
                if ((a.y > point.y) != (b.y > point.y) && point.x < (b.x - a.x) * (point.y - a.y) / (b.y - a.y) + a.x) inside = !inside;
            }
            return inside;
        }
    }
